<body>
  <div class="wrap">
    <div class="header">
      <h1>Nike Inc. (NKE) Historical Stock Performance Analysis (2000–2026)</h1>
      <p class="sub">Data window: 2000-01-03 to 2026-01-30 · 6,559 trading days · Audience: Investors</p>
    </div>

    <div class="section">
      <h2>Executive Summary</h2>
      <div class="kpi-grid">
        <div class="kpi"><div class="label">Cumulative Return</div><div class="value">+1,282.35%</div><div class="meta">$4.47 → $61.81</div></div>
