      <h2>Trading Volume Patterns</h2>
      <div id="volumePriceChart" class="chart"></div>
      <div class="two-col">
        <div>
          <table>
            <thead><tr><th>Era</th><th>Avg Daily Volume</th></tr></thead>
            <tbody>
              <tr><td>2000–2009</td><td>12.96M</td></tr>
              <tr><td>2010–2019</td><td>9.00M</td></tr>
              <tr><td>2020–2026</td><td>9.64M</td></tr>
            </tbody>
          </table>
        </div>
