        <li>Volatility clustering (notably 2020 and 2024–2025) suggests position sizing and rebalancing discipline matter as much as directional view.</li>
        <li>For long-horizon allocators, historical evidence supports combining quality-growth exposure with explicit risk controls for deep cyclical resets.</li>
      </ul>
      <p class="note">All values in this report are calculated directly from `/app/benchmark/data.csv` without estimation.</p>
    </div>
  </div>

<script>
fetch('/app/benchmark/data.csv').then(r=>r.text()).then(text=>{
  const lines=text.trim().split('\n');
  const headers=lines[0].split(',');
  const idx={}; headers.forEach((h,i)=>idx[h.trim()]=i);
  const d=[], close=[], high=[], low=[], vol=[];
  for(let i=1;i<lines.length;i++){
    const p=lines[i].split(',');
    const dt=new Date(p[idx['Date']]);
    d.push(dt); close.push(+p[idx['Close']]); high.push(+p[idx['High']]); low.push(+p[idx['Low']]); vol.push(+p[idx['Volume']]);
  }
  const range=high.map((h,i)=>h-low[i]);
  const ret=[null]; for(let i=1;i<close.length;i++) ret.push(close[i]/close[i-1]-1);
  const roll20=Array(close.length).fill(null);
  for(let i=19;i<ret.length;i++){
    const w=ret.slice(i-19,i+1).filter(v=>v!==null);
    const m=w.reduce((a,b)=>a+b,0)/w.length;
    const variance=w.reduce((a,b)=>a+(b-m)*(b-m),0)/(w.length-1);
    roll20[i]=Math.sqrt(variance)*Math.sqrt(252);
  }

  Plotly.newPlot('priceChart',[
    {x:d,y:close,type:'scatter',mode:'lines',line:{color:'#1d4ed8',width:2},name:'Close'}
  ],{margin:{t:20,r:20,b:40,l:60},paper_bgcolor:'#fff',plot_bgcolor:'#fff',xaxis:{title:'Date'},yaxis:{title:'Close (USD)'},showlegend:false}, {displayModeBar:false,responsive:true});

  Plotly.newPlot('rangeChart',[
    {x:d,y:range,type:'scatter',mode:'lines',line:{color:'#6b7280',width:1},name:'Daily High-Low Spread'}
  ],{margin:{t:20,r:20,b:40,l:60},xaxis:{title:'Date'},yaxis:{title:'High-Low (USD)'},showlegend:false}, {displayModeBar:false,responsive:true});

  Plotly.newPlot('volChart',[
    {x:d,y:roll20,type:'scatter',mode:'lines',line:{color:'#b91c1c',width:1.5},name:'20D Annualized Volatility'}
  ],{margin:{t:20,r:20,b:40,l:60},xaxis:{title:'Date'},yaxis:{title:'Volatility'},showlegend:false}, {displayModeBar:false,responsive:true});

  Plotly.newPlot('volumePriceChart',[
    {x:d,y:vol,type:'bar',marker:{color:'#cbd5e1'},name:'Volume',yaxis:'y'},
    {x:d,y:close,type:'scatter',mode:'lines',line:{color:'#047857',width:2},name:'Close',yaxis:'y2'}
  ],{margin:{t:20,r:20,b:40,l:60},xaxis:{title:'Date'},yaxis:{title:'Volume (Shares)'},yaxis2:{title:'Close (USD)',overlaying:'y',side:'right'},legend:{orientation:'h'}}, {displayModeBar:false,responsive:true});

  const yearLast={};
  for(let i=0;i<d.length;i++){ yearLast[d[i].getFullYear()]=close[i]; }
  const ys=Object.keys(yearLast).map(x=>+x).sort((a,b)=>a-b);
  const yr=[], rv=[];
  for(let i=1;i<ys.length;i++){ yr.push(ys[i]); rv.push((yearLast[ys[i]]/yearLast[ys[i-1]]-1)*100); }

  Plotly.newPlot('annualReturnChart',[
    {x:yr,y:rv,type:'bar',marker:{color:rv.map(v=>v>=0?'#2563eb':'#dc2626')}}
  ],{margin:{t:20,r:20,b:40,l:60},xaxis:{title:'Year'},yaxis:{title:'Return (%)'}}, {displayModeBar:false,responsive:true});
});
</script>
</body>
</html>
